1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
7	
8	/**
9	 * Rejects creating an owner whose household — see {@link HouseholdKey} — is already used by
10	 * another (existing) owner. A match on a different owner escalates as a 409 via
11	 * {@link DuplicateHouseholdException}.
12	 *
13	 * <p>The check is skipped when the request set {@code sharesHousehold} true (published by
14	 * {@link BuildOwner}): such owners are allowed to share a household.
15	 */
16	public class RejectDuplicateHousehold {
17	
18	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(sharesHousehold)) {
21	            return;
22	        }
23	        HouseholdKey household = HouseholdKey.of(owner);
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
26	                continue;
27	            }
28	            if (household.matches(existing)) {
29	                throw new DuplicateHouseholdException(
30	                        "Another owner already shares this household (same last name and address)");
31	            }
32	        }
33	    }
34	}
