1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * The identity of a household: the same last name and the same address, compared
10	 * case-insensitively with runs of whitespace collapsed to a single space (and trimmed), so
11	 * e.g. "110  W.  Liberty St." matches "110 w. liberty st.".
12	 *
13	 * <p>Single-sources the "what is a household" definition shared by
14	 * {@link RejectDuplicateHousehold} (who is rejected) and {@link AssignHousehold} (who shares a
15	 * {@code householdId}); the two steps must agree on it, so it lives in exactly one place.
16	 */
17	final class HouseholdKey {
18	
19	    private final String lastName;
20	
21	    private final String address;
22	
23	    private HouseholdKey(String lastName, String address) {
24	        this.lastName = lastName;
25	        this.address = address;
26	    }
27	
28	    /** The household the given owner belongs to. */
29	    static HouseholdKey of(Owner owner) {
30	        return new HouseholdKey(normalize(owner.getLastName()), normalize(owner.getAddress()));
31	    }
32	
33	    /** Whether {@code owner} belongs to this household. */
34	    boolean matches(Owner owner) {
35	        return equals(of(owner));
36	    }
37	
38	    /** Stable canonical form of the key, suitable for deriving a shared identifier. */
39	    String canonical() {
40	        return lastName + "|" + address;
41	    }
42	
43	    @Override
44	    public boolean equals(Object o) {
45	        if (this == o) {
46	            return true;
47	        }
48	        if (!(o instanceof HouseholdKey other)) {
49	            return false;
50	        }
51	        return lastName.equals(other.lastName) && address.equals(other.address);
52	    }
53	
54	    @Override
55	    public int hashCode() {
56	        return Objects.hash(lastName, address);
57	    }
58	
59	    @Override
60	    public String toString() {
61	        return canonical();
62	    }
63	
64	    /** Lower-case, trim, and collapse any run of whitespace to a single space. */
65	    private static String normalize(String value) {
66	        if (value == null) {
67	            return "";
68	        }
69	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
70	    }
71	}
