3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode} on create, formatted {@code <LAST3>-<NNNN>}
9	 * where {@code LAST3} is the upper-cased first three letters of the last name and
10	 * {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than the
11	 * current number of owners (e.g. {@code SMI-0007}).
12	 */
13	public class AssignOwnerCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String lastName = owner.getLastName();
17	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
18	        int sequence = ownerRepository.findAll().size() + 1;
19	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
20	    }
21	}
