1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Single source of truth for the owner "E.164 telephone" rule. Both
5	 * {@link NormalizeOwnerTelephone} (which stores the E.164 value) and
6	 * {@link RejectDuplicateTelephone} (which compares against it) go through here, so the two
7	 * can never drift apart.
8	 *
9	 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country
10	 * code when present, otherwise assume country code {@code '+61'} and drop a single leading
11	 * {@code '0'} from the national digits; require 8 to 15 digits after the {@code '+'}. So
12	 * {@code "0412 345 678"} becomes {@code "+61412345678"}.
13	 */
14	final class OwnerTelephones {
15	
16	    private OwnerTelephones() {
17	    }
18	
19	    /**
20	     * Converts {@code telephone} to its E.164 form, or returns {@code null} when it cannot
21	     * form a valid E.164 number (null input, non-digit content, or fewer than 8 / more than
22	     * 15 digits after the {@code '+'}).
23	     */
24	    static String toE164(String telephone) {
25	        if (telephone == null) {
26	            return null;
27	        }
28	        // Strip spaces, dashes and brackets; any other non-digit is left in place so it
29	        // fails the digits check below.
30	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
31	        String digits;
32	        if (cleaned.startsWith("+")) {
33	            // Explicit country code: keep it, drop the leading '+'.
34	            digits = cleaned.substring(1);
35	        } else {
36	            // No country code: assume '+61' and drop a single leading '0' from the national
37	            // digits.
38	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
39	            digits = "61" + national;
40	        }
41	        if (!digits.matches("\\d{8,15}")) {
42	            return null;
43	        }
44	        return "+" + digits;
45	    }
46	}
