          pattern: "^[\\p{L}]+([ '-][\\p{L}]+){0,2}\\.?$"
        address:
          title: Address
          description: The postal address of the pet owner.
          type: string
          minLength: 1
          maxLength: 255
          pattern: '.*\S.*'
          example: '110 W. Liberty St.'
        city:
          type: string
          minLength: 1
          maxLength: 80
          pattern: '.*\S.*'
        telephone:
          type: string
          minLength: 1
          maxLength: 20
        email:
          type: string
          maxLength: 255
        registrationDate:
          type: string
          format: date
        sharesHousehold:
          title: Shares household
          description: >-
            Create-time flag. ... Set true to allow sharing a household and skip
